pub fn accept_outside(
    &mut self,
    mut proposal: Proposal,
    cx: &mut Context<Self>,
) -> Result<(), String> {
    self.settle_target(&mut proposal);
    let id = proposal.id.clone();
    if self.proposal(&id).is_none() {
        self.proposals.push(proposal);
    }
    self.accept(&id, cx).map(|_| ())
}
pub(super) fn accept_proposal(
    &mut self,
    proposal: planning::Proposal,
    cx: &mut Context<Self>,
) -> Result<(), String> {
    let planning = self.planning(cx).ok_or("Open a project first.")?;
    planning.update(cx, |planning, cx| planning.accept_outside(proposal, cx))
